import React, { useState, useEffect, useMemo } from "react";
import { attendanceAPI } from "./api_service";

const COLORS = {
  primary: "#4F46E5",
  primaryLight: "#EEF2FF",
  success: "#10B981",
  successLight: "#DCFCE7",
  danger: "#EF4444",
  dangerLight: "#FEE2E2",
  warning: "#F59E0B",
  warningLight: "#FEF3C7",
  textMain: "#1E293B",
  textMuted: "#64748B",
  border: "#E2E8F0",
  background: "#F8FAFC",
  surface: "#FFFFFF"
};

const Dashboard = () => {
  const [stats, setStats] = useState({
    active_students: 0,
    present_today: 0,
    absent_today: 0,
    summary: {
      unique_students: 0,
      total_records: 0,
      avg_confidence: 0,
      max_confidence: 0,
      min_confidence: 0
    }
  });

  const [attendanceLog, setAttendanceLog] = useState([]);
  const [statusList, setStatusList] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [autoRefresh, setAutoRefresh] = useState(false);
  const [lastUpdated, setLastUpdated] = useState(new Date());

  const loadData = async () => {
    try {
      if (attendanceLog.length === 0) setLoading(true);

      const [studentStatsRes, attendanceStatsRes, logRes, statusRes] = await Promise.all([
        attendanceAPI.getStudentStats(),   // /students/stats/
        attendanceAPI.getStats(),          // /attendance/stats/
        attendanceAPI.getTodayLog(),       // /attendance/
        attendanceAPI.getStatus()          // /attendance/status/
      ]);

      // Extraction sécurisée (gère res.data ou res.data.data)
      const studentStats = studentStatsRes?.data?.data || studentStatsRes?.data || {};
      const attendanceSummary = attendanceStatsRes?.data?.data || attendanceStatsRes?.data || {};

      setStats({
        active_students: Number(studentStats.active_students) || 0,
        present_today: Number(studentStats.total_attendance) || 0,
        absent_today: Math.max(
          0,
          (Number(studentStats.active_students) || 0) - (Number(studentStats.total_attendance) || 0)
        ),
        summary: {
          unique_students: Number(attendanceSummary.unique_students) || 0,
          total_records: Number(attendanceSummary.total_records) || 0,
          avg_confidence: Number(attendanceSummary.avg_confidence) || 0,
          max_confidence: Number(attendanceSummary.max_confidence) || 0,
          min_confidence: Number(attendanceSummary.min_confidence) || 0
        }
      });

      // Journal des entrées (gère si la réponse est directement un tableau ou un objet avec 'records')
      const logs = logRes?.data?.records || logRes?.data || [];
      setAttendanceLog(Array.isArray(logs) ? logs : []);

      // Statut général (gère si la réponse est directement un tableau ou un objet avec 'students')
      const students = statusRes?.data?.students || statusRes?.data || [];
      setStatusList(Array.isArray(students) ? students : []);

      setLastUpdated(new Date());
      setError(null);

    } catch (err) {
      console.error("❌ Erreur Dashboard API:", err);
      setError("Erreur de liaison avec le serveur. Vérifiez que le backend est lancé.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  useEffect(() => {
    let timer;
    if (autoRefresh) {
      timer = setInterval(loadData, 10000);
    }
    return () => clearInterval(timer);
  }, [autoRefresh]);

  const statCards = useMemo(() => {
    const total = stats.active_students || 0;
    const present = stats.present_today || 0;
    const rate = total > 0 ? Math.round((present / total) * 100) : 0;

    return [
      { id: 'total', label: "Étudiants Inscrits", value: total, icon: "👥", color: COLORS.primary, bgColor: COLORS.primaryLight },
      { id: 'present', label: "Présents (Aujourd'hui)", value: present, icon: "✅", color: COLORS.success, bgColor: COLORS.successLight },
      { id: 'absent', label: "Absents", value: stats.absent_today, icon: "❌", color: COLORS.danger, bgColor: COLORS.dangerLight },
      { id: 'rate', label: "Taux de Présence", value: `${rate}%`, icon: "📈", color: "#8B5CF6", bgColor: "#F5F3FF" }
    ];
  }, [stats]);

  if (loading) {
    return (
      <div style={styles.loaderContainer}>
        <style>{`@keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }`}</style>
        <div style={styles.spinner}></div>
        <p style={styles.loaderText}>Chargement des données biométriques...</p>
      </div>
    );
  }

  return (
    <div style={styles.pageWrapper}>
      <header style={styles.header}>
        <div>
          <h1 style={styles.title}>Dashboard de Présence</h1>
          <p style={styles.subtitle}>Dernière mise à jour : {lastUpdated.toLocaleTimeString()}</p>
        </div>

        <div style={styles.actions}>
          <label style={styles.switchContainer}>
            <input 
              type="checkbox" 
              checked={autoRefresh} 
              onChange={() => setAutoRefresh(!autoRefresh)}
              style={styles.switchInput}
            />
            <span style={styles.switchLabel}>Auto-Refresh (10s)</span>
          </label>
          <button onClick={loadData} style={styles.refreshBtn}>
            🔄 Actualiser
          </button>
        </div>
      </header>

      {error && (
        <div style={styles.errorAlert}>
          <span style={{marginRight: 10}}>⚠️</span> {String(error)}
        </div>
      )}

      <div style={styles.statsGrid}>
        {statCards.map((card) => (
          <div key={card.id} style={styles.statCard}>
            <div style={{...styles.iconWrapper, backgroundColor: card.bgColor, color: card.color}}>
              {card.icon}
            </div>
            <div style={styles.statInfo}>
              <span style={styles.statLabel}>{card.label}</span>
              <span style={styles.statValue}>{card.value}</span>
            </div>
          </div>
        ))}
      </div>

      <div style={styles.mainLayout}>
        <section style={styles.sectionCard}>
          <div style={styles.sectionHeader}>
            <h3 style={styles.sectionTitle}>Journal des Entrées</h3>
            <span style={styles.badgeCount}>{attendanceLog.length} scans aujourd'hui</span>
          </div>
          <div style={styles.tableResponsive}>
            <table style={styles.table}>
              <thead>
                <tr>
                  <th style={styles.th}>Étudiant</th>
                  <th style={styles.th}>Heure de passage</th>
                  <th style={styles.th}>Confiance IA</th>
                </tr>
              </thead>
              <tbody>
                {attendanceLog.length > 0 ? (
                  attendanceLog.map((row, idx) => (
                    <tr key={idx} style={styles.tr}>
                      <td style={styles.tdBold}>{row.student || 'Inconnu'}</td>
                      <td style={styles.td}>{row.timestamp || '—'}</td>
                      <td style={styles.td}>
                        <div style={{
                          ...styles.confidenceBadge,
                          backgroundColor: (row.confidence || 0) > 0.8 ? COLORS.successLight : COLORS.warningLight,
                          color: (row.confidence || 0) > 0.8 ? COLORS.success : COLORS.warning
                        }}>
                          {((row.confidence || 0) * 100).toFixed(1)}%
                        </div>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="3" style={styles.emptyCell}>Aucune activité détectée aujourd'hui.</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </section>

        <aside style={styles.rightColumn}>
          <section style={styles.sectionCard}>
            <h3 style={styles.sectionTitle}>Analyse de Précision</h3>
            <div style={styles.analyticsGrid}>
              <div style={styles.analyticRow}>
                <span style={styles.analyticLabel}>Confiance Max</span>
                <span style={{...styles.analyticValue, color: COLORS.success}}>
                  {(stats.summary.max_confidence * 100).toFixed(1)}%
                </span>
              </div>
              <div style={styles.analyticRow}>
                <span style={styles.analyticLabel}>Moyenne</span>
                <span style={{...styles.analyticValue, color: COLORS.primary}}>
                  {(stats.summary.avg_confidence * 100).toFixed(1)}%
                </span>
              </div>
              <div style={styles.divider}></div>
              <div style={styles.analyticRow}>
                <span style={styles.analyticLabel}>Total scans</span>
                <span style={styles.analyticValue}>{stats.summary.total_records}</span>
              </div>
            </div>
          </section>
        </aside>
      </div>
    </div>
  );
};

const styles = {
  pageWrapper: { padding: "40px", backgroundColor: COLORS.background, minHeight: "100vh", fontFamily: "'Inter', sans-serif" },
  header: { display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: "35px" },
  title: { fontSize: "28px", fontWeight: "800", color: COLORS.textMain, margin: 0 },
  subtitle: { fontSize: "14px", color: COLORS.textMuted, marginTop: "5px" },
  actions: { display: "flex", alignItems: "center", gap: "20px" },
  refreshBtn: { padding: "10px 20px", backgroundColor: COLORS.primary, color: "white", border: "none", borderRadius: "10px", fontWeight: "600", cursor: "pointer" },
  switchContainer: { display: "flex", alignItems: "center", gap: "8px", cursor: "pointer" },
  switchLabel: { fontSize: "13px", color: COLORS.textMuted },
  errorAlert: { padding: "15px 20px", backgroundColor: COLORS.dangerLight, color: COLORS.danger, borderRadius: "12px", marginBottom: "25px", border: `1px solid ${COLORS.danger}` },
  statsGrid: { display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(240px, 1fr))", gap: "25px", marginBottom: "35px" },
  statCard: { backgroundColor: COLORS.surface, padding: "20px", borderRadius: "15px", display: "flex", alignItems: "center", gap: "15px", border: `1px solid ${COLORS.border}` },
  iconWrapper: { width: "50px", height: "50px", borderRadius: "12px", display: "flex", alignItems: "center", justifyContent: "center", fontSize: "20px" },
  statInfo: { display: "flex", flexDirection: "column" },
  statLabel: { fontSize: "13px", color: COLORS.textMuted },
  statValue: { fontSize: "22px", fontWeight: "800", color: COLORS.textMain },
  mainLayout: { display: "grid", gridTemplateColumns: "2fr 1fr", gap: "30px" },
  sectionCard: { backgroundColor: COLORS.surface, borderRadius: "15px", padding: "25px", border: `1px solid ${COLORS.border}` },
  sectionHeader: { display: "flex", justifyContent: "space-between", marginBottom: "20px" },
  sectionTitle: { fontSize: "17px", fontWeight: "700", color: COLORS.textMain, margin: 0 },
  badgeCount: { fontSize: "11px", padding: "4px 10px", backgroundColor: COLORS.primaryLight, color: COLORS.primary, borderRadius: "15px" },
  tableResponsive: { overflowX: "auto" },
  table: { width: "100%", borderCollapse: "collapse" },
  th: { textAlign: "left", padding: "12px", borderBottom: `2px solid ${COLORS.background}`, color: COLORS.textMuted, fontSize: "12px", textTransform: "uppercase" },
  tr: { borderBottom: `1px solid ${COLORS.background}` },
  td: { padding: "12px", fontSize: "14px" },
  tdBold: { padding: "12px", fontSize: "14px", fontWeight: "600" },
  confidenceBadge: { display: "inline-block", padding: "4px 8px", borderRadius: "6px", fontSize: "11px", fontWeight: "700" },
  analyticsGrid: { display: "flex", flexDirection: "column", gap: "15px" },
  analyticRow: { display: "flex", justifyContent: "space-between" },
  analyticLabel: { fontSize: "13px", color: COLORS.textMuted },
  analyticValue: { fontSize: "15px", fontWeight: "700" },
  divider: { height: "1px", backgroundColor: COLORS.border },
  loaderContainer: { height: "100vh", display: "flex", flexDirection: "column", justifyContent: "center", alignItems: "center" },
  spinner: { width: "40px", height: "40px", border: `4px solid ${COLORS.primaryLight}`, borderTopColor: COLORS.primary, borderRadius: "50%", animation: "spin 1s linear infinite" },
  loaderText: { marginTop: "15px", color: COLORS.textMuted },
  emptyCell: { textAlign: "center", padding: "30px", color: COLORS.textMuted, fontStyle: "italic" }
};

export default Dashboard;
